const fs = require('fs');
let hasSummary = false;
try {
  if (fs.existsSync('/files/temp/global_summary.json')) {
    const s = JSON.parse(fs.readFileSync('/files/temp/global_summary.json', 'utf8'));
    hasSummary = Boolean(s && (s.game || s.global_summary));
  }
} catch (e) {}
const base = $('Load Cached Telemetry').first().json || {};
return [{ pairedItem: { item: 0 }, json: { ...base, _has_cached_summary: hasSummary } }];

const fs = require('fs');
try {
  const raw = ($input.first() && ($input.first().json.output || $input.first().json.text)) || '';
  if (raw) {
    const b3 = String.fromCharCode(96).repeat(3);
    const cleaned = String(raw).split(b3 + 'json').join('').split(b3).join('').trim();
    const parsed = JSON.parse(cleaned);
    if (parsed && (parsed.game || parsed.global_summary)) {
      fs.writeFileSync('/files/temp/global_summary.json', JSON.stringify(parsed, null, 2));
    }
  }
} catch (e) {}
const base = $('Load Cached Telemetry').first().json || {};
return [{ pairedItem: { item: 0 }, json: base }];

const fs = require('fs');
const items = $input.all().map(i => i.json);
let words = [];
let indexDoc = null;
let globalSummary = {};
try {
  const lct = $('Load Cached Telemetry').first().json || {};
  words = lct.words || [];
  if (lct.annotated_sentences && lct.annotated_sentences.length) indexDoc = { annotated_sentences: lct.annotated_sentences };
} catch (e) {}
if (words.length === 0) {
  try {
    if (fs.existsSync('/files/temp/transcript.json')) {
      const tj = JSON.parse(fs.readFileSync('/files/temp/transcript.json', 'utf8'));
      words = tj.words || (tj.x_groq && tj.x_groq.words) || [];
    }
  } catch (e) {}
}
if (!indexDoc) {
  try {
    if (fs.existsSync('/files/temp/unified_timeline_index.json')) {
      indexDoc = JSON.parse(fs.readFileSync('/files/temp/unified_timeline_index.json', 'utf8'));
    }
  } catch (e) {}
}
try {
  if (fs.existsSync('/files/temp/global_summary.json')) globalSummary = JSON.parse(fs.readFileSync('/files/temp/global_summary.json', 'utf8'));
} catch (e) {}

const fmtTC = (sec) => {
  const sTot = Math.max(0, Number(sec) || 0);
  const m = Math.floor(sTot / 60);
  const s = (sTot % 60).toFixed(2).padStart(5, '0');
  return `${String(m).padStart(2, '0')}:${s}`;
};
const annotatedSentences = (indexDoc && indexDoc.annotated_sentences) || [];
const getWordsBetween = (t0, t1) => words.filter(w => {
  const mid = (Number(w.start || 0) + Number(w.end || w.start || 0)) * 0.5;
  return mid >= t0 && mid <= t1;
}).map(w => String(w.word || '').trim()).join(' ').trim();
const getTagsInWindow = (t0, t1) => {
  const set = new Set();
  for (const s of annotatedSentences) {
    if (Number(s.end || 0) >= t0 - 0.5 && Number(s.start || 0) <= t1 + 0.5) {
      for (const tg of (s.tags || [])) set.add(tg);
    }
  }
  return Array.from(set);
};

const grouped = new Map();
for (const it of items) {
  if (it.error) continue;
  const key = `${it.clip_number || 1}::${it.clip_title || 'Clip'}`;
  if (!grouped.has(key)) {
    grouped.set(key, {
      clip_number: it.clip_number || 1,
      title: it.clip_title,
      clip_title: it.clip_title,
      hook_caption: it.hook_caption,
      theme: it.theme || 'Gaming',
      narrative_archetype: it.narrative_archetype || 'CONTINUOUS_GAMEPLAY_CLUTCH_OR_FAIL',
      virality_score: Number(it.virality_score ?? it.viral_score ?? 8.5),
      payoff_time: Number(it.payoff_time) || 0,
      total_duration_sec: 0,
      edl_segments: [],
      assembled_spoken_script: it.assembled_spoken_script || '',
      signal_justification: it.signal_justification || {},
      cause_and_effect_setup: it.cause_and_effect_setup || '',
      entity_continuity_check: it.entity_continuity_check || { passed: true },
    });
  }
  const entry = grouped.get(key);
  entry.edl_segments.push({
    segment_order: it.segment_order,
    role: it.role || 'CONTINUOUS_ARC',
    start: it.start,
    end: it.end,
    start_tc: fmtTC(it.start),
    end_tc: fmtTC(it.end),
    duration: it.duration,
    spoken_text: it.spoken_text || getWordsBetween(Number(it.start) || 0, Number(it.end) || 0),
    signal_tags_in_window: getTagsInWindow(Number(it.start) || 0, Number(it.end) || 0),
  });
  entry.total_duration_sec = Number((entry.total_duration_sec + (Number(it.duration) || 0)).toFixed(2));
}

return Array.from(grouped.values()).map((p, idx) => {
  p.edl_segments.sort((a, b) => a.segment_order - b.segment_order);
  p.segment_count = p.edl_segments.length;
  const firstStart = p.edl_segments[0] ? Number(p.edl_segments[0].start) : 0;
  const lastEnd = p.edl_segments.length ? Number(p.edl_segments[p.edl_segments.length - 1].end) : 0;
  const prior10 = words.filter(w => {
    const mid = (Number(w.start || 0) + Number(w.end || w.start || 0)) * 0.5;
    return mid >= Math.max(0, firstStart - 15.0) && mid < firstStart - 0.02;
  }).slice(-10).map(w => String(w.word || '').trim()).filter(Boolean).join(' ');
  p.pre_hook_context_text = prior10 || getWordsBetween(Math.max(0, firstStart - 15.0), Math.max(0, firstStart - 0.02));
  p.post_payoff_context_text = getWordsBetween(lastEnd + 0.05, lastEnd + 5.0);
  p.assembled_spoken_script = p.edl_segments.map(s => s.spoken_text).filter(Boolean).join(' ') || p.assembled_spoken_script;
  const timedLines = p.edl_segments.map(s => `[${s.role} ${s.start_tc}-${s.end_tc}] ${s.spoken_text}`).join('\n');
  p.timecoded_transcript = `GAME: ${globalSummary.game || 'Roblox'}\nCLIP TITLE: ${p.title}\nDIRECTOR PROPOSED HOOK: ${p.hook_caption}\n\n${timedLines}`;
  return { pairedItem: { item: idx }, json: p };
});

const fs = require('fs');
const mergeItems = $input.all().map(i => i.json);
let baseClips = [];
try { baseClips = $('Prepare Merge Items').all().map(i => i.json); } catch (e) {}

let globalSummary = {};
try {
  if (fs.existsSync('/files/temp/global_summary.json')) {
    globalSummary = JSON.parse(fs.readFileSync('/files/temp/global_summary.json', 'utf8'));
  }
} catch (e) {}

const BANNED_RE = /^(I CALLED TIME OUT|HE ACTUALLY FELL FOR IT|THAT DOES NOT COUNT|MY WORST BLUNDER|MUST WATCH MOMENT|VIRAL MOMENT|PLAYING THE GAME|PLAYING THE GAME WRONG|GAMEPLAY HIGHLIGHT CLIP|WATCH THIS CLIP|NO WORDS|NO AUDIO FOUND|NO TRANSCRIPT|UNDEFINED|NULL|ERROR)$/i;
const FOREIGN_GAME_RE = /\b(RUST|TOWER OF HELL|FORTNITE|MINECRAFT|VALORANT|APEX|AMONG US|CSGO|GTA|BEDWARS|BROOKHAVEN|BLOXBURG)\b/i;
const HOOK_COMMON = new Set(["WHAT","WHEN","WHY","HOW","THIS","THAT","WAIT","ONLY","EVER","BEST","WORST","REAL","FAKE","ACTUALLY","LITERALLY","STOP","NEVER","MOMENT","GAMING","INSANE","CRAZY","CHAOS","CAUGHT","BUSTED","TRAPPED","SCAM","CLUTCH","ROAST","FAIL","RAGE","SHOCK","BETRAYAL","MYSTERY","KARMA"]);

const DANGLING_END_HOOK_RE = /\b(TO|A|AN|THE|OF|IN|ON|AT|FOR|WITH|FROM|BY|AND|OR|BUT|IF|IS|ARE|WAS|WERE|DO|DOES|DID|NOT|WANT|GOING|HAVE|HAS|MY|YOUR|OUR|THEIR|THIS|THAT)$/i;
function verifyHook(candidate, fallbackHook, clipSpeech, clipTitle, extraCtx) {
  const ctxLower = (String(clipTitle || '') + ' ' + String(extraCtx || '') + ' ' + JSON.stringify(globalSummary)).toLowerCase();
  const sanitizeHook = (v) => {
    let cleaned = String(v || '').replace(/[^\x20-\x7E]/g, '').replace(/[{}\x27\x22`$()<>]/g, '').replace(/_/g, ' ').replace(/\s+/g, ' ').trim().toUpperCase();
    if (/\bcoolest\b/i.test(ctxLower)) cleaned = cleaned.replace(/\bCOLDEST\b/g, 'COOLEST');
    cleaned = cleaned.replace(/\bRAGE\s+BADER\b/g, 'RAGE BAITER');
    let wds = cleaned.split(' ').filter(Boolean);
    if (wds.length > 6) wds = wds.slice(0, 6);
    if (wds.length >= 2 && wds.length < 6 && DANGLING_END_HOOK_RE.test(wds[wds.length - 1]) && clipSpeech) {
      const mTail = String(clipSpeech).match(new RegExp(wds.slice(-2).join('\\s+') + '\\s+([A-Za-z0-9\x27]+)', 'i'));
      if (mTail && mTail[1] && !DANGLING_END_HOOK_RE.test(mTail[1])) wds.push(mTail[1].toUpperCase());
    }
    while (wds.length > 3 && DANGLING_END_HOOK_RE.test(wds[wds.length - 1])) wds.pop();
    while (wds.length > 3 && wds.join(' ').length > 32) wds.pop();
    return wds.join(' ');
  };
  const safeTitle = sanitizeHook(clipTitle);
  const corpus = (JSON.stringify(globalSummary) + ' ' + String(clipSpeech || '') + ' ' + String(clipTitle || '') + ' ' + String(extraCtx || '')).toLowerCase();
  const speechCorpus = (JSON.stringify(globalSummary) + ' ' + String(clipSpeech || '')).toLowerCase();
  const isClean = (txt) => {
    if (!txt || txt.length < 3 || BANNED_RE.test(txt) || DANGLING_END_HOOK_RE.test(txt)) return false;
    const fg = txt.match(FOREIGN_GAME_RE);
    if (fg && !speechCorpus.includes(fg[0].toLowerCase())) return false;
    const nouns = (txt.toLowerCase().match(/[a-z0-9]{4,}/g) || []).filter(w => !HOOK_COMMON.has(w.toUpperCase()));
    if (nouns.length > 0 && (nouns.filter(w => !corpus.includes(w)).length / nouns.length) > 0.5) return false;
    return true;
  };
  const cand = sanitizeHook(candidate);
  const fb = sanitizeHook(fallbackHook);
  const candWc = cand ? cand.split(' ').filter(Boolean).length : 0;
  const fbWc = fb ? fb.split(' ').filter(Boolean).length : 0;
  if (isClean(cand) && candWc >= 3 && candWc <= 6) return cand;
  if (isClean(fb) && fbWc >= 3 && fbWc <= 6) return fb;
  if (isClean(safeTitle) && safeTitle.split(' ').length >= 3) return safeTitle;
  return isClean(cand) ? cand : (isClean(fb) ? fb : 'WATCH THIS CLIP NOW');
}

const previews = (baseClips.length > 0 ? baseClips : mergeItems).map((clip, idx) => {
  const mRaw = mergeItems[idx] ? String(mergeItems[idx].output || mergeItems[idx].text || '') : '';
  let parsed = {};
  if (mRaw) {
    try {
      const b3 = String.fromCharCode(96).repeat(3);
      parsed = JSON.parse(mRaw.split(b3 + 'json').join('').split(b3).join('').trim());
    } catch (e) {}
  }
  const allSegTags = (clip.edl_segments || []).flatMap(s => s.signal_tags_in_window || []);
  const viewerVoice = allSegTags.some(t => t.includes('VIEWER_OR_GAME_VOICE'));
  const sig = clip.signal_justification || {};
  const finalHook = verifyHook(parsed.story_hook, clip.hook_caption, clip.assembled_spoken_script, clip.title, (clip.theme || '') + ' ' + (clip.cause_and_effect_setup || ''));
  return {
    clip_number: clip.clip_number || (idx + 1),
    title: clip.title,
    final_top_hook_caption: finalHook,
    narrative_archetype: clip.narrative_archetype,
    virality_score: clip.virality_score || 0,
    total_duration_sec: clip.total_duration_sec,
    segment_count: clip.segment_count || (clip.edl_segments ? clip.edl_segments.length : 0),
    edl_segments: clip.edl_segments || [],
    assembled_spoken_script: clip.assembled_spoken_script || '',
    pre_hook_context_text: clip.pre_hook_context_text || '',
    post_payoff_context_text: clip.post_payoff_context_text || '',
    signal_justification: {
      chat_burst: allSegTags.find(t => t.includes('CHAT_BURST') || t.includes('LAUGH_BURST') || t.includes('CHAT_QUESTION_CLUSTER')) || 'NONE',
      db_spike: allSegTags.find(t => t.includes('SCREAM') || t.includes('dB_PEAK')) || 'NONE',
      face_emotion: allSegTags.find(t => t.includes('FACE:')) || 'NONE',
      viewer_voice_present: sig.viewer_voice_present !== undefined ? Boolean(sig.viewer_voice_present) : viewerVoice,
    },
    cause_and_effect_setup: clip.cause_and_effect_setup || '',
    entity_continuity_check: clip.entity_continuity_check || { passed: true },
    climax_quote: parsed.climax_quote || '',
    memes: parsed.memes || []
  };
});

try {
  fs.writeFileSync('/files/temp/n8n_sandbox_edl_preview.json', JSON.stringify(previews, null, 2));
} catch (e) {}

return previews.map(p => ({ json: p }));
